gsap.registerPlugin(ScrollTrigger);

const lenis = new Lenis({
	smooth: true,
	direction: 'vertical',
});

function raf(time) {
	lenis.raf(time);
	requestAnimationFrame(raf);
}

requestAnimationFrame(raf);

gsap.registerPlugin(ScrollTrigger);

ScrollTrigger.scrollerProxy(document.body, {
	getBoundingClientRect() {
		return {
			top: 0,
			left: 0,
			width: window.innerWidth,
			height: window.innerHeight
		};
	},
	pinType: document.body.style.transform ? "transform" : "fixed",
});

document.addEventListener("DOMContentLoaded", () => {
	gsap.matchMedia().add("(min-width: 768px) and (prefers-reduced-motion: no-preference)", () => {
		document.querySelectorAll("[data-parallax-layers]").forEach((triggerElement) => {
			gsap.to(triggerElement.querySelector("[data-parallax-layer]"), {
				yPercent: -7,
				ease: "none",
				scrollTrigger: {
					trigger: triggerElement,
					start: "-10% 0%",
					end: "bottom top",
					scrub: true,
				},
			});
		});
	});
});

document.addEventListener("DOMContentLoaded", () => {
	const counters = document.querySelectorAll(".counter");
	const countersFloat = document.querySelectorAll(".counter-float");

	counters.forEach(counter => {
		const endValue = counter.getAttribute("data-end-value");
		const triggerCounter = document.querySelector('.trig-counter');

		let tl = gsap.timeline({
			scrollTrigger: {
				trigger: triggerCounter,
				start: "120% 120%",
			}
		});

		tl.to(
			{ value: 0 },
			{
				value: endValue,
				duration: 3,
				onUpdate: function () {
					counter.innerText = Math.ceil(this.targets()[0].value);
				},
				ease: "power1.out",
			}
		);
	});

	countersFloat.forEach(counterFloat => {
		const endValue = counterFloat.getAttribute("data-end-value");
		const triggerCounter = document.querySelector('.trig-counter');

		let tl = gsap.timeline({
			scrollTrigger: {
				trigger: triggerCounter,
				start: "120% 120%",
			}
		});

		tl.to(
			{ value: 0 },
			{
				value: endValue,
				duration: 3,
				onUpdate: function () {
					counterFloat.innerText = this.targets()[0].value.toFixed(3);
				},
				ease: "power1.out",
			}
		);
	});
});
const availableApartmentsList = document.querySelector('.available-apartments__list');
if (availableApartmentsList) {


	if (window.innerWidth > 768) {
		lenis.on('wheel', (event) => {
			if (availableApartmentsList.contains(event.target)) {
				return true;
			}
		});
		availableApartmentsList.addEventListener('wheel', (e) => {
			e.stopPropagation();
		});
	}
}

const createOdometer = (el, value) => {
	const odometer = new Odometer({
		el: el,
		value: 0,
	});

	let hasRun = false;

	const options = {
		threshold: [0, 0.9],
	};

	const callback = (entries, observer) => {
		entries.forEach((entry) => {
			if (entry.isIntersecting) {
				if (!hasRun) {
					odometer.update(value);
					hasRun = true;
				}
			}
		});
	};

	const observer = new IntersectionObserver(callback, options);
	observer.observe(el);
};

const residentialOdometer = document.querySelector(".residential-odometer");
createOdometer(residentialOdometer, 23762);

const commercialOdometer = document.querySelector(".commercial-odometer");
createOdometer(commercialOdometer, 17);

const buildingsOdometer = document.querySelector(".buildings-odometer");
createOdometer(buildingsOdometer, 4);

const apartmentsOdometer = document.querySelector(".apartments-odometer");
createOdometer(apartmentsOdometer, 384);

